#include "story.hpp"
#include "audio.hpp"
#include <sstream>
#include <algorithm>
extern "C" {
#include "font.h"
}
#include <SDL.h>
#include <filesystem>
#include <iostream>
#include <memory>
#include <cstring>
static std::vector<uint32_t> utf8(const std::string&s){std::vector<uint32_t>o;for(size_t p=0;p<s.size();){unsigned c=uint8_t(s[p++]),n=0;if(c>=240){c&=7;n=3;}else if(c>=224){c&=15;n=2;}else if(c>=192){c&=31;n=1;}for(unsigned i=0;i<n;i++){if(p==s.size())throw std::runtime_error("Truncated UTF8");c=(c<<6)|(uint8_t(s[p++])&63);}o.push_back(c);}return o;}
struct Frontend {
 qlie::Assets assets;whj2::Story story;std::unique_ptr<whj2::Audio>audio;std::map<std::string,std::map<std::string,std::string>>audioTemplates;std::array<float,3>volumes{{0.4f,1.f,1.f}};std::array<bool,3>loops{{true,false,false}};std::array<unsigned,3>audioTimes{{1500,0,0}};KFont*font=nullptr;SDL_Window*window=nullptr;SDL_Renderer*renderer=nullptr;SDL_Texture*texture=nullptr;qlie::Bytes pixels;std::string text,name,status="画面・音声の接続は開発中です。",saveDir;bool menu=true,done=false,hidden=false;int focus=0;unsigned advances=0;
 Frontend(const std::string&game,const std::string&saves):assets(game),story(assets),pixels(1280*720*4),saveDir(saves){if(SDL_Init(SDL_INIT_VIDEO|SDL_INIT_AUDIO|SDL_INIT_GAMECONTROLLER|SDL_INIT_EVENTS))throw std::runtime_error(SDL_GetError());window=SDL_CreateWindow("WHJ2 native runtime - development",SDL_WINDOWPOS_CENTERED,SDL_WINDOWPOS_CENTERED,1280,720,SDL_WINDOW_RESIZABLE);if(!window)throw std::runtime_error(SDL_GetError());renderer=SDL_CreateRenderer(window,-1,SDL_RENDERER_ACCELERATED|SDL_RENDERER_PRESENTVSYNC);if(!renderer)renderer=SDL_CreateRenderer(window,-1,SDL_RENDERER_SOFTWARE);if(!renderer)throw std::runtime_error(SDL_GetError());SDL_RenderSetLogicalSize(renderer,1280,720);texture=SDL_CreateTexture(renderer,SDL_PIXELFORMAT_ARGB8888,SDL_TEXTUREACCESS_STREAMING,1280,720);font=kfont_open(nullptr,0);if(!font||!texture)throw std::runtime_error("Font/texture initialization failed");std::filesystem::create_directories(saveDir);audio=std::make_unique<whj2::Audio>();for(auto type:{"music","sound"}){std::istringstream in(qlie::cp932(assets.read(std::string("avg/imoscripter_template_")+type+".txt")));std::string l;while(std::getline(in,l)){auto p=l.find(61);if(p!=l.npos)audioTemplates[type][whj2::trim(l.substr(0,p))]=whj2::trim(l.substr(p+1));}}}
 ~Frontend(){audio.reset();kfont_close(font);if(texture)SDL_DestroyTexture(texture);if(renderer)SDL_DestroyRenderer(renderer);if(window)SDL_DestroyWindow(window);SDL_Quit();}
 void line(const std::string&s,int x,int y,int size=26,uint32_t color=0xffffff){KImage dst{0,0,1280,720,1280*4,pixels.data()};int start=x;for(auto cp:utf8(s)){int width=cp<128?size/2:size;if(cp==10||x+width>1230){x=start;y+=size+10;if(cp==10)continue;}if(y+size>710)break;kfont_draw(font,&dst,cp,x,y,width,size,color);x+=width;}}
 std::string expandAudio(std::string s,const std::string&type){std::vector<std::pair<std::string,std::string>>values(audioTemplates[type].begin(),audioTemplates[type].end());std::sort(values.begin(),values.end(),[](const auto&a,const auto&b){return a.first.size()>b.first.size();});for(unsigned pass=0;pass<12;pass++){bool changed=false;for(auto&v:values){size_t p=0;while((p=s.find(v.first,p))!=s.npos){s.replace(p,v.first.size(),v.second);p+=v.second.size();changed=true;}}if(!changed)return s;}throw std::runtime_error("Audio template recursion");}
 bool audioCommand(const std::string&line){auto p=line.find(44);std::string cmd=line.substr(1,p-1);if(cmd!="music01"&&cmd!="se01"&&cmd!="se02")return false;unsigned ch=cmd=="music01"?0:cmd=="se01"?1:2;std::string type=ch==0?"music":"sound";auto tokens=whj2::split(expandAudio(p==line.npos?"":line.substr(p+1),type),44);std::map<std::string,std::string>attrs;for(auto&t:tokens){if(t.empty())continue;auto c=t.find(58);if(c==t.npos)throw std::runtime_error("Unknown audio template "+t);attrs[t.substr(0,c)]=t.substr(c+1);}for(auto&v:attrs)if(v.first!="file"&&v.first!="loop"&&v.first!="vol"&&v.first!="time"&&v.first!="clear")throw std::runtime_error("Unsupported audio property "+v.first);if(attrs.count("clear")){audio->volume(ch,0,0,true);return true;}if(attrs.count("loop"))loops[ch]=attrs["loop"]=="true";if(attrs.count("vol"))volumes[ch]=std::stof(attrs["vol"])/100.f*(ch==0?0.4f:1.f);if(attrs.count("time"))audioTimes[ch]=unsigned(std::stoul(attrs["time"]));unsigned ms=audioTimes[ch];if(attrs.count("file")){auto f=attrs["file"];if(f=="none"){audio->volume(ch,0,ms,true);return true;}std::string path=(ch==0?"music/":"se/")+f;if(!assets.exists(path))path+=".ogg";if(!assets.exists(path))throw std::runtime_error("Missing audio "+path);audio->play(ch,assets.read(path),loops[ch],volumes[ch],ms);}else audio->volume(ch,volumes[ch],ms);return true;}
 void next(){if(menu||story.state.finished)return;for(unsigned guard=0;guard<10000;guard++){auto e=story.next();if(e.type=="choice"){focus=0;text="選択してください";return;}if(e.type=="finish"||e.type=="finished"){menu=true;text="";status="物語の終了地点に到達しました。";return;}if(e.type=="text"){
  if(e.value.rfind("【",0)==0){name=e.value;continue;}
  if(e.value.rfind("％",0)==0){std::cerr<<"VOICE-ID unresolved: "<<e.file<<":"<<e.line<<"\n";continue;}
  text=e.value;advances++;std::cerr<<"TEXT "<<e.file<<":"<<e.line<<"\n";return;
 }if(e.type=="command"&&audioCommand(e.value))continue;if(e.type=="create"||e.type=="free")audio->stopAll();if(e.type=="command"||e.type=="create"||e.type=="free"||e.type=="wait"||e.type=="audio-clear"||e.type=="audio-volume"){
  // Preserve every unrendered event in the frontend trace; these are explicitly
  // pending rendering work, never counted as multimedia acceptance.
  std::cerr<<"PENDING-PRESENT "<<e.type<<" "<<e.file<<":"<<e.line<<"\n";continue;
 }throw std::runtime_error("Unhandled frontend event "+e.type);}throw std::runtime_error("Frontend event budget");}
 void save(){if(menu)return;auto b=story.save();qlie::write_file(saveDir+"/slot01.story",b);qlie::Bytes t(text.begin(),text.end());qlie::write_file(saveDir+"/slot01.text",t);qlie::Bytes n(name.begin(),name.end());qlie::write_file(saveDir+"/slot01.name",n);status="論理状態を保存しました（画面状態の保存は開発中）。";}
 void load(){story.restore(qlie::file(saveDir+"/slot01.story"));auto t=qlie::file(saveDir+"/slot01.text"),n=qlie::file(saveDir+"/slot01.name");text.assign(t.begin(),t.end());name.assign(n.begin(),n.end());menu=false;focus=0;status="論理状態を読み込みました。";}
 void activate(){if(menu){if(focus==0){story.start();menu=false;name="";next();}else if(focus==1)load();else done=true;}else if(story.state.awaiting){story.choose(unsigned(focus));next();}else next();}
 void draw(){for(size_t i=0;i<pixels.size();i+=4){pixels[i]=35;pixels[i+1]=25;pixels[i+2]=20;pixels[i+3]=255;}line("美少女万華鏡２　日文移植 開発版",45,30,32);line(status,45,90,20,0xffd58b);if(menu){std::vector<std::string>items={"はじめから","論理状態をロード","終了"};for(int i=0;i<3;i++)line((focus==i?"▶ ":"　 ")+items[size_t(i)],100,210+i*70,30);}else if(!hidden){line(name,55,185,28,0xffddbb);line(text,55,245,28);if(story.state.awaiting)for(size_t i=0;i<story.state.choices.size();i++)line((focus==int(i)?"▶ ":"　 ")+story.state.choices[i],80,450+int(i)*50,26);}line("Enter / クリック: 次へ　↑↓: 選択　F5: 保存　F9: 読込　Esc: タイトル",45,675,19,0xb0becf);SDL_UpdateTexture(texture,nullptr,pixels.data(),1280*4);SDL_RenderClear(renderer);SDL_RenderCopy(renderer,texture,nullptr,nullptr);SDL_RenderPresent(renderer);}
 int run(unsigned smoke){unsigned frames=0;while(!done){SDL_Event e;while(SDL_PollEvent(&e)){if(e.type==SDL_QUIT)done=true;else if(e.type==SDL_KEYDOWN&&!e.key.repeat){auto k=e.key.keysym.sym;int count=menu?3:int(story.state.choices.size());if(k==SDLK_UP&&count)focus=(focus+count-1)%count;else if(k==SDLK_DOWN&&count)focus=(focus+1)%count;else if(k==SDLK_RETURN||k==SDLK_SPACE)activate();else if(k==SDLK_F5)save();else if(k==SDLK_F9)load();else if(k==SDLK_ESCAPE){menu=true;focus=0;}else if(k==SDLK_h)hidden=!hidden;}else if(e.type==SDL_MOUSEBUTTONDOWN&&e.button.button==SDL_BUTTON_LEFT){float x,y;SDL_RenderWindowToLogical(renderer,e.button.x,e.button.y,&x,&y);if(menu&&y>=210&&y<420)focus=int((y-210)/70);else if(!menu&&story.state.awaiting&&y>=450){int n=int((y-450)/50);if(n>=0&&n<int(story.state.choices.size()))focus=n;}activate();}}draw();if(smoke){if(frames==1)activate();if(frames==3)next();if(frames==4)save();if(frames==5){auto before=story.save();std::string expected=text;load();if(story.save()!=before||text!=expected)throw std::runtime_error("Frontend save/load mismatch");}if(++frames>=smoke){SDL_Surface*surface=SDL_CreateRGBSurfaceFrom(pixels.data(),1280,720,32,1280*4,0x00ff0000,0x0000ff00,0x000000ff,0xff000000);if(!surface||SDL_SaveBMP(surface,(saveDir+"/smoke.bmp").c_str()))throw std::runtime_error("Cannot save smoke frame");SDL_FreeSurface(surface);done=true;}}else SDL_Delay(5);}auto ast=audio->stats();std::cerr<<"AUDIO output_frames="<<ast.frames<<" nonzero_frames="<<ast.nonzero<<"\n";std::cerr<<"EXIT normal text_advances="<<advances<<" frames="<<frames<<"\n";return 0;}
};
int main(int argc,char**argv){try{if(argc<2){std::cerr<<"usage: whj2-runtime GAME [SAVE_DIR] [--smoke-frames N]\n";return 2;}unsigned smoke=0;std::string saves=argc>2?argv[2]:"local/saves";if(argc>4&&std::string(argv[3])=="--smoke-frames")smoke=unsigned(std::stoul(argv[4]));Frontend f(argv[1],saves);return f.run(smoke);}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
